import torch


def run_correctness(input, tensor1, tensor2, value):
    result = input.float().addcdiv_(
        tensor1.float(), tensor2.float(), value=value
    )
    input.copy_(result.to(input.dtype))
    return input


def run(input, tensor1, tensor2, value):
    return input.addcdiv_(tensor1, tensor2, value=value)
